SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции2002.YEAR, Станции2002.NUST, Станции2002.E, Станции2002.EOTP, Станции2002.EURT, Станции2002.EUST, Станции2002.Q, Станции2002.TURT, Станции2002.TUST, Станции2002.B, Станции2002.GAZ, Станции2002.MAZUT, Станции2002.TORF, Станции2002.SLAN, Станции2002.GTT, Станции2002.PROCH, Станции2002.UGOL, Станции2002.DON, Станции2002.PODM, Станции2002.PECH, Доп_угли2002.int, Доп_угли2002.vork, Станции2002.ARKT, Станции2002.KUZN, Станции2002.URAL, Доп_угли2002.sver, Доп_угли2002.chel, Доп_угли2002.kizel, Станции2002.BASHK, Станции2002.EKIB, Станции2002.KARAG, Станции2002.KAN, Доп_угли2002.nazar, Доп_угли2002.ibor, Доп_угли2002.berez, Доп_угли2002.per, Станции2002.IRKUT, Доп_угли2002.azey, Доп_угли2002.cher, Доп_угли2002.jer, Станции2002.HAK, Станции2002.TUV, Станции2002.BUR, Доп_угли2002.gusin, Доп_угли2002.tugn, Станции2002.CHIT, Доп_угли2002.har, Доп_угли2002.urt, Станции2002.[YAKUT] AS Выражение1, Станции2002.[AMUR] AS Выражение2, Станции2002.URG, Станции2002.PRIM, Станции2002.LUCH, Станции2002.MAG, Станции2002.SAH, Станции2002.USHUM, Станции2002.QOTR, Станции2002.SNK, Станции2002.EWTP, Станции2002.NT, Станции2002.OBOR, Станции2002.VED, Станции2002.OBL, Станции2002.DEP, Станции2002.OES, Станции2002.ER, Станции2002.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group]
FROM (((Станции2002 INNER JOIN Имена_станций ON Станции2002.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции2002.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции2002.OBL=Имена_областей.OBL) LEFT JOIN Доп_угли2002 ON (Станции2002.YEAR=Доп_угли2002.YEAR) AND (Станции2002.NUMB1120=Доп_угли2002.NUMB1120);
